 ('415a0c1f-3b07-5a52-94a0-6bd450bba6c5'::uuid, 'toefl', 'D021', 'Code is alphanumeric (D021), not numeric. MIT does not require official sending; self-report on the application.', '4b8d4121-a160-5388-8103-814cd5039dd7'::uuid),
