 ('415a0c1f-3b07-5a52-94a0-6bd450bba6c5'::uuid, 'duolingo', null, 'No DET code or recipient instruction on MIT''s page. Self-report on the application; official sending not required.', '7ee93e92-bdb7-5457-bbbe-83ed51d0cf41'::uuid),
 ('415a0c1f-3b07-5a52-94a0-6bd450bba6c5'::uuid, 'pte', null, 'No PTE code on MIT''s page. Self-report on the application; official sending not required.', '7ee93e92-bdb7-5457-bbbe-83ed51d0cf41'::uuid),
 ('03e19bf0-cc16-5613-af62-bc77fcd4412d'::uuid, 'sat', '4704', 'Stanford does not require official scores for review; self-report, official scores only if enrolling (https://admission.stanford.edu/apply/first-year/testing.html).', '2bdbeae2-f930-5fe0-9982-0ea99eeac667'::uuid),
