 ('d7b0e604-36c4-57ec-8afa-11e1217143fe'::uuid, 'pte', null, 'PTE is not listed among Purdue''s English proficiency options.', 'b79d9a94-638e-57f4-b5db-919da5d069ab'::uuid),
 ('caa9a1af-8f82-5061-8a81-0334c772233f'::uuid, 'sat', '4833', 'Berkeley is test-free: SAT/ACT are not used in admissions; scores are only used for placement/credit after admission.', '0e525c26-8427-58c1-80c5-12ed9d41ca57'::uuid),
 ('caa9a1af-8f82-5061-8a81-0334c772233f'::uuid, 'act', '0444', 'From Berkeley''s Central Evaluation Unit. Berkeley is test-free; scores are used only for placement/credit after admission.', 'd8ef477e-1526-5319-b78a-3ca5a9280a76'::uuid),
 ('caa9a1af-8f82-5061-8a81-0334c772233f'::uuid, 'toefl', '4833', 'Page says ''Our code to submit official TOEFL and SAT scores through ETS is 4833.'' UC site says self-report English scores in the UC application and send official scores after admission only to the campus where you enroll.', '0e525c26-8427-58c1-80c5-12ed9d41ca57'::uuid),
 ('caa9a1af-8f82-5061-8a81-0334c772233f'::uuid, 'ielts', null, 'No IELTS code published. Self-report in the UC application; send official scores after admission to the enrolling campus only.', '8812f1b7-841d-50ed-9cc0-ffb5ed2e107c'::uuid),
 ('caa9a1af-8f82-5061-8a81-0334c772233f'::uuid, 'duolingo', null, 'Berkeley accepts DET (min 115) but no code published. Self-report in the UC application; send official scores after admission to the enrolling campus only.', '8812f1b7-841d-50ed-9cc0-ffb5ed2e107c'::uuid),
 ('caa9a1af-8f82-5061-8a81-0334c772233f'::uuid, 'pte', null, 'PTE is not listed among Berkeley''s accepted English proficiency exams (TOEFL, IELTS, DET).', '0e525c26-8427-58c1-80c5-12ed9d41ca57'::uuid)
